const today = () => { const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const prettyDate = value => value ? new Date(value+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Date to be chosen';
const loadDrafts = () => { try {const v=JSON.parse(localStorage.getItem('adigyogi-car-enquiries-v2')||'[]');return Array.isArray(v)?v:[];}catch{return [];} };
const saveDrafts = arr => {try {localStorage.setItem('adigyogi-car-enquiries-v2',JSON.stringify(arr));return true;}catch{return false;} };
